sol_sql:
['-------------------------------------------------------------------------
-- Create a Function to Calculate Credit Health Score (CHS)
-- -----------------------------------------------------------------------
-- This function computes the composite Credit Health Score (CHS)
-- according to KB "Credit Health Score (CHS)" (KB id:5):
-- Step 1: Define the input parameters.
-- Step 2: Calculate each component using arithmetic and typecasting.
-- Step 3: Sum up the components for the final CHS value.
CREATE OR REPLACE FUNCTION calculate_credit_health_score(
    p_credscore    SMALLINT,
    p_credutil     NUMERIC(5,3),
    p_debincratio  NUMERIC(5,3),
    p_credageyrs   SMALLINT,
    p_delinqcount  SMALLINT,
    p_latepaycount SMALLINT,
    p_choffs       SMALLINT,
    p_bankr        SMALLINT
)
RETURNS NUMERIC(5,3)
LANGUAGE plpgsql
AS $$
DECLARE
    comp1 NUMERIC(5,3);
    comp2 NUMERIC(5,3);
    comp3 NUMERIC(5,3);
    comp4 NUMERIC(5,3);
    comp5 NUMERIC(5,3);
    total NUMERIC(5,3);
BEGIN
    -- Step 1: Compute 0.4 * (credscore/850)
    comp1 := 0.4 * (p_credscore::NUMERIC / 850);
    -- Step 2: Compute 0.2 * (1 - credutil)
    comp2 := 0.2 * (1 - p_credutil);
    -- Step 3: Compute 0.2 * (1 - debincratio)
    comp3 := 0.2 * (1 - p_debincratio);
    -- Step 4: Compute 0.1 * (credageyrs/20)
    comp4 := 0.1 * (p_credageyrs::NUMERIC / 20);
    -- Step 5: Compute 0.1 * (1 - ((delinqcount + latepaycount + choffs + bankr)/10))
    comp5 := 0.1 * (1 - ((p_delinqcount + p_latepaycount + p_choffs + p_bankr)::NUMERIC / 10));
    -- Final CHS computed as the sum of the individual components.
    total := comp1 + comp2 + comp3 + comp4 + comp5;
    RETURN total;
END;
$$;
']

tool_trajectory:
[{'type': 'tool', 'tool': 'submit_sql', 'args': {'sql': 'CREATE OR REPLACE FUNCTION calculate_chs(
    p_credit_score NUMERIC,
    p_credit_utilization_ratio NUMERIC,
    p_debt_to_income_ratio NUMERIC,
    p_credit_age_years NUMERIC,
    p_delinquency_count INTEGER,
    p_late_payment_count INTEGER,
    p_charge_offs INTEGER,
    p_bankruptcies INTEGER
)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_chs NUMERIC;
BEGIN
    /*
      Credit Health Score (CHS) heuristic (0-100):
      - Base from credit score (300-850) scaled to 0-60
      - Utilization penalty up to 15
      - DTI penalty up to 10
      - Credit age bonus up to 5
      - Negative events penalties:
          delinquency up to 4, late payments up to 3,
          charge-offs up to 2, bankruptcies up to 1
      Final score clamped to [0,100].
    */

    v_chs := 0;

    -- 1) Credit score contribution (0..60)
    v_chs := v_chs + LEAST(60, GREATEST(0, ((p_credit_score - 300) / 550.0) * 60));

    -- 2) Utilization penalty (0..15)
    v_chs := v_chs - LEAST(15, GREATEST(0, p_credit_utilization_ratio) * 15);

    -- 3) DTI penalty (0..10)
    v_chs := v_chs - LEAST(10, GREATEST(0, p_debt_to_income_ratio) * 10);

    -- 4) Credit age bonus (0..5), maxed at 20 years
    v_chs := v_chs + LEAST(5, GREATEST(0, p_credit_age_years) / 20.0 * 5);

    -- 5) Event penalties
    v_chs := v_chs - LEAST(4, GREATEST(0, p_delinquency_count) * 1.0);
    v_chs := v_chs - LEAST(3, GREATEST(0, p_late_payment_count) * 0.5);
    v_chs := v_chs - LEAST(2, GREATEST(0, p_charge_offs) * 1.0);
    v_chs := v_chs - LEAST(1, GREATEST(0, p_bankruptcies) * 1.0);

    -- Clamp to [0,100]
    v_chs := LEAST(100, GREATEST(0, v_chs));

    RETURN ROUND(v_chs, 3);
END;
$$;'}, 'result': 'Incorrect. Your SQL is not correct.', 'steps_before': 30, 'steps_after': 29}]

sol_sql:
['
ALTER TABLE transactions ADD COLUMN adjusted_esccomprate NUMERIC;

UPDATE transactions
SET adjusted_esccomprate = (
    SELECT esccomprate
    FROM markets
    WHERE markets.mktregistry = transactions.mktref
);       

CREATE INDEX idx_transaction_anomaly ON transactions (
    (payamtusd/1000 * txfinishhrs/24 * (1 + escrowhrs::numeric/100) * (1 - adjusted_esccomprate/100))
);
']
